"""Shared Jinja templates: strict missing fields and escaped text by default."""
from pathlib import Path

from jinja2 import Environment, FileSystemLoader, StrictUndefined, select_autoescape
from markupsafe import Markup

environment = Environment(
    loader=FileSystemLoader(Path(__file__).parent),
    autoescape=select_autoescape(['html', 'xml']),
    undefined=StrictUndefined,
    keep_trailing_newline=True,
)


def render_template(name, **context):
    return environment.get_template(name).render(**context)


def table(headers, rows):
    # Only markup generated by our escaping template is marked trusted.
    return Markup(render_template('templates/table.html', headers=headers, rows=rows).rstrip())
